package org.canpshell.mobile;
import android.app.*;import android.content.*;import android.net.VpnService;import android.os.*;import android.view.*;import android.widget.*;
public final class AndroidMachineVpnActivity extends Activity {
 private TextView status;private final Handler timer=new Handler();private final Runnable refresh=new Runnable(){public void run(){status.setText(AndroidMachineVpnService.state);timer.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout body=new LinearLayout(this);body.setOrientation(1);int pad=(int)(24*getResources().getDisplayMetrics().density);body.setPadding(pad,pad,pad,pad);ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);TextView title=new TextView(this);title.setText("手机网络出口");title.setTextSize(24);body.addView(title);TextView detail=new TextView(this);detail.setText("先在 CShell 的网络与代理中，将这台手机指定到所需机器出口，再在此开启。\n\n支持其他应用的 TCP 与域名访问；UDP、QUIC、ICMP 不转发。CShell 的控制连接不进入 VPN，应用内访问仍使用自己的机器代理设置。\n\n出口失效时保持拦截。系统撤销授权、进程结束或手动关闭 VPN 后，Android 可能恢复原网络；当前不支持始终开启模式，请勿将其作为系统永久断网保护。\n\n不会自动替换你正在使用的其他 VPN。");detail.setTextSize(15);detail.setPadding(0,pad,0,pad);body.addView(detail);status=new TextView(this);body.addView(status);Button start=new Button(this);start.setText("授权并开启");body.addView(start);start.setOnClickListener(v->prepare());Button stop=new Button(this);stop.setText("关闭网络出口");body.addView(stop);stop.setOnClickListener(v->{stopService(new Intent(this,AndroidMachineVpnService.class));AndroidMachineVpnService.state="已关闭";});Button back=new Button(this);back.setText("返回");body.addView(back);back.setOnClickListener(v->finish());if(!AndroidMachineVpnService.available()){start.setEnabled(false);AndroidMachineVpnService.state="需要 Android 10 或更新系统，以及包含网络组件的正式安装包";}timer.post(refresh);}
 private void prepare(){if(AndroidMachineVpnService.active())return;if(AndroidMachineVpnService.anotherVpn(this)){AndroidMachineVpnService.state="已有其他 VPN 正在运行；请先在系统设置中自行处理后再试。";return;}try{AndroidAgentService.networkProxy().port();}catch(Exception e){AndroidMachineVpnService.state="请先启用 CAgent，并在 CShell 中为此手机选择可用的机器出口。";return;}Intent request=VpnService.prepare(this);if(request!=null)startActivityForResult(request,42);else startForegroundService(new Intent(this,AndroidMachineVpnService.class));}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42&&result==RESULT_OK){if(AndroidMachineVpnService.anotherVpn(this)){AndroidMachineVpnService.state="其他 VPN 已启动，未更改现有连接。";return;}startForegroundService(new Intent(this,AndroidMachineVpnService.class));}}
 @Override public void onDestroy(){timer.removeCallbacks(refresh);super.onDestroy();}
}
